package io.knowledgebrain.learning;
import io.knowledgebrain.contracts.learning.courseprogress.v1.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;
import org.apache.kafka.clients.consumer.*;import org.apache.kafka.common.serialization.*;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_LEARNING_KAFKA_BOOTSTRAP",matches=".+")
class CourseProgressKafkaIntegrationTest {
 @Test void enrollmentCdcBytesAndUnacknowledgedReplay()throws Exception{
  var f=new CourseProgressStoreIntegrationTest();f.setup();var v=f.change(0,0,"IN_PROGRESS");f.change(1,0,"COMPLETED");f.change(2,1,"COMPLETED");var expected=new HashMap<String,byte[]>();for(var bytes:f.sql.queryForList("SELECT payload FROM outbox_event WHERE aggregateid=?",byte[].class,v.progressId())){var e=CourseProgressEnvelopeV1.parseFrom(bytes);expected.put(e.getEventId(),bytes);}assertEquals(3,expected.size());
  var options=new Properties();options.put("bootstrap.servers",System.getenv("BRAIN_TEST_LEARNING_KAFKA_BOOTSTRAP"));options.put("group.id","learning-validation-"+UUID.randomUUID());options.put("enable.auto.commit","false");options.put("auto.offset.reset","earliest");options.put("key.deserializer",StringDeserializer.class.getName());options.put("value.deserializer",ByteArrayDeserializer.class.getName());options.put("security.protocol","SSL");options.put("ssl.endpoint.identification.algorithm","HTTPS");options.put("ssl.truststore.type","PEM");options.put("ssl.keystore.type","PEM");options.put("ssl.truststore.certificates",Files.readString(Path.of("/learning-kafka-test/ca.crt")));options.put("ssl.keystore.certificate.chain",Files.readString(Path.of("/learning-kafka-test/user.crt")));options.put("ssl.keystore.key",Files.readString(Path.of("/learning-kafka-test/user.key")));
  for(int replay=0;replay<2;replay++){var seen=new HashSet<String>();try(var consumer=new KafkaConsumer<String,byte[]>(options)){consumer.subscribe(List.of("learning.course-progress.v1"));long deadline=System.nanoTime()+Duration.ofSeconds(60).toNanos();while(seen.size()<3&&System.nanoTime()<deadline)for(var record:consumer.poll(Duration.ofMillis(300))){var e=CourseProgressEnvelopeV1.parseFrom(record.value());if(!expected.containsKey(e.getEventId()))continue;assertArrayEquals(expected.get(e.getEventId()),record.value());assertEquals(e.getAggregateId(),record.key());assertEquals(f.trace,e.getTraceId());assertEquals(f.ref.spaceId().toString(),e.getSpaceId());assertEquals("CourseProgress",e.getAggregateType());var p=CourseProgressSnapshotV1.parseFrom(e.getPayload());assertEquals(v.progressId().toString(),p.getProgressId());assertEquals(f.ref.principalId().toString(),p.getParticipantId());assertEquals("PARTICIPANT_ONLY",p.getAudience());assertEquals(3,p.getCourseVersion());for(var entry:Map.of("trace_id",f.trace,"schema_group","learning","schema_artifact","course-progress-events","schema_version","1").entrySet())assertEquals(entry.getValue(),new String(record.headers().lastHeader(entry.getKey()).value(),StandardCharsets.UTF_8));seen.add(e.getEventId());}}assertEquals(expected.keySet(),seen);}
  System.out.println("PASS learning.course-progress.v1 three byte-exact Course progress snapshots, stable IDs, trace/schema headers and unacknowledged replay");
 }
}
